ALTER TABLE "event_requests" ADD COLUMN "confirmed_by_id" text;--> statement-breakpoint
ALTER TABLE "event_requests" ADD COLUMN "confirmed_by_name" text;--> statement-breakpoint
ALTER TABLE "event_requests" ADD COLUMN "confirmed_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "event_requests" ADD CONSTRAINT "event_requests_confirmation_matches_status" CHECK (("event_requests"."status"::text = 'confirmed' and "event_requests"."confirmed_by_id" is not null and btrim("event_requests"."confirmed_by_id") <> '' and "event_requests"."confirmed_by_name" is not null and btrim("event_requests"."confirmed_by_name") <> '' and "event_requests"."confirmed_at" is not null) or ("event_requests"."status"::text in ('completed', 'cancelled') and (("event_requests"."confirmed_by_id" is not null and btrim("event_requests"."confirmed_by_id") <> '' and "event_requests"."confirmed_by_name" is not null and btrim("event_requests"."confirmed_by_name") <> '' and "event_requests"."confirmed_at" is not null) or ("event_requests"."confirmed_by_id" is null and "event_requests"."confirmed_by_name" is null and "event_requests"."confirmed_at" is null))) or ("event_requests"."status"::text not in ('confirmed', 'completed', 'cancelled') and "event_requests"."confirmed_by_id" is null and "event_requests"."confirmed_by_name" is null and "event_requests"."confirmed_at" is null));